style.css:
/* Velvet Paradise — Roblox */

:root {
  /* change these colors if you want */
  --my-black: #090708;
  --my-charcoal: #171114;
  --my-burgundy: #501c2b;
  --my-gold: #c5a16a;
  --my-cream: #e8d9d1;
}

/* dark luxury background */
body {
  background-color: var(--my-black) !important;
  color: var(--my-cream) !important;
  font-family: Georgia, serif !important;
}

/* elegant links */
a {
  color: var(--my-gold) !important;
  transition: color 0.3s ease !important;
}

a:hover {
  color: #e8b5c2 !important;
}

/* luxury buttons */
button {
  background: linear-gradient(135deg, #30151f, #120c10) !important;
  color: var(--my-cream) !important;
  border: 1px solid var(--my-gold) !important;
  border-radius: 8px !important;
}

/* dark inputs */
input, textarea {
  background: #171114 !important;
  color: var(--my-cream) !important;
  border: 1px solid #704453 !important;
}

/* vintage image styling */
img {
  border-radius: 6px !important;
}

/* lace-inspired luxury accents */
hr {
  border: none !important;
  border-top: 1px solid var(--my-gold) !important;
  opacity: 0.5 !important;
}
